  'progress.howToReadBody': '“शुरू किया” का अर्थ है कम से कम एक दर्ज प्रयास। “अभ्यास किया” पाँच प्रयासों की एक सीधी-सादी दिखाने वाली सीमा है, कोई सीखने से जुड़ा निर्णय नहीं। सटीकता केवल ब्योरा है, और तब तक नहीं दिखाई जाती जब तक उसके पीछे पर्याप्त उत्तर न हों: कुल दस, किसी अध्याय में पाँच। जिस सही उत्तर में संकेत, ट्यूटर की मदद या दूसरा मौका लगा, वह सही ही गिना जाता है, पर उसे अलग से बताया जाता है। दक्षता का आकलन, पुनरावृत्ति का समय और Pri Explain — ये सब सीखने वाली परत के ज़िम्मे हैं।',

