  'settings.helpSafety': 'मदद और सुरक्षा',
  'settings.helpBodyIndia': 'हर अध्याय की एक कौशल रेटिंग होती है जो हर उत्तर के साथ बदलती है — कठिन प्रश्न उसे ज़्यादा बदलते हैं। स्मार्ट अभ्यास लगभग 70% सफलता का लक्ष्य रखता है और टॉपिक भूलने से पहले उनकी पुनरावृत्ति बीच-बीच में डालता है। अंक अनुमान केवल पेपर के उन हिस्सों को कवर करता है जिनका आपने अभ्यास किया है, और यह उसे कभी CBSE प्रतिशत, JEE पर्सेंटाइल या रैंक में नहीं बदलता — घर के अभ्यास से इनमें से कोई भी ईमानदारी से नहीं निकाला जा सकता। हाथ से लिखे उत्तर ऑनलाइन होने पर Pri के सर्वर रीडर द्वारा पढ़े जाते हैं, और फिर उसी इंजन से पंक्ति दर पंक्ति जाँचे जाते हैं जो टाइप किए उत्तरों को जाँचता है। संकेत और दोबारा कोशिश पर भी श्रेय मिलता है, बस थोड़ा कम।',
  'settings.helpBody': 'हर टॉपिक की एक कौशल रेटिंग होती है जो हर उत्तर के साथ बदलती है — कठिन प्रश्न उसे ज़्यादा बदलते हैं। स्मार्ट अभ्यास लगभग 70% सफलता का लक्ष्य रखता है, टॉपिक भूलने से पहले उनकी पुनरावृत्ति बीच-बीच में डालता है, और अंक अनुमानक पूरे पाठ्यक्रम में दक्षता को परीक्षा के भार के हिसाब से तौलता है। हाथ से लिखे उत्तर ऑनलाइन होने पर Pri के सर्वर रीडर द्वारा पढ़े जाते हैं, और फिर उसी इंजन से पंक्ति दर पंक्ति जाँचे जाते हैं जो टाइप किए उत्तरों को जाँचता है। संकेत और दोबारा कोशिश पर भी श्रेय मिलता है, बस थोड़ा कम।',
  'settings.addToHomeScreen': ' पूरे स्क्रीन वाले ऐप के लिए: अपने ब्राउज़र में “Add to Home Screen” चुनें।',

