  'snap.lead': 'अपनी पाठ्यपुस्तक या वर्कशीट से एक प्रश्न की फ़ोटो लें। Pri बताता है कि यह किस अध्याय और कौशल का प्रश्न है, फिर उसी कौशल पर नए प्रश्न देता है।',
