  'placement.title': 'स्तर-जाँच',
  'placement.introLead': 'लगभग 10 प्रश्न — 12 से कभी ज़्यादा नहीं — यह अनुमान लगाने के लिए कि आप किस स्तर पर हैं, और किसी संभावित कमी को उसकी संभावित जड़ तक ले जाने के लिए।',
  'placement.introHow': 'जाँच आपकी कक्षा से शुरू होती है। गलत उत्तर पर अगला प्रश्न उस विषय पर जाता है जिस पर यह टिका है; साफ़ सही उत्तर पर अगला प्रश्न ऊपर जाता है। उत्तर अपनी लिखावट में दीजिए, या चाहें तो टाइप कीजिए।',
  'placement.introMarking': 'हर उत्तर Pri के निश्चित (deterministic) मार्कर से जाँचा जाता है — वही जो अभ्यास में इस्तेमाल होता है। कोई AI अंक तय नहीं करता।',
  'placement.introEvidence': 'परिणाम कुछ प्रश्नों से मिला नैदानिक प्रमाण है, दक्षता का अंक नहीं। इससे आपके XP, लगातार दिन या अभ्यास का इतिहास कभी नहीं बदलता। हाँ, जिन अध्यायों का आपने अभी अभ्यास नहीं किया, उनमें स्मार्ट अभ्यास का क्रम बदलता है: जहाँ कमी मिली, वे अध्याय पहले आते हैं और आसान स्तर से शुरू होते हैं। आप इसे कभी भी दोबारा दे सकते हैं।',
