  'misconception.inequalityNotReversed.explain': 'दोनों पक्षों को किसी ऋणात्मक संख्या से गुणा या भाग करने पर असमिका का चिह्न पलट जाता है।',
  'misconception.distributePartial.name': 'कोष्ठक केवल आंशिक रूप से खोला गया',
  'misconception.distributePartial.explain': 'कोष्ठक के बाहर की संख्या अंदर के हर पद से गुणा होती है: a(b + c) = ab + ac।',
  'misconception.distributeSign.name': 'ऋण चिह्न केवल पहले पद पर लगाया गया',
  'misconception.distributeSign.explain': 'कोष्ठक के आगे का ऋण चिह्न अंदर के हर पद का चिह्न बदलता है: a − (b + c) = a − b − c।',
  'misconception.powerOfSum.name': 'योग का वर्ग पद-दर-पद किया गया',
  'misconception.powerOfSum.explain': '(a + b)² = a² + 2ab + b² होता है, a² + b² नहीं। बीच का पद 2ab छूटना नहीं चाहिए।',
  'misconception.combinedUnlikeTerms.name': 'असमान पद जोड़ दिए गए',
  'misconception.combinedUnlikeTerms.explain': 'केवल समान पद जोड़े जा सकते हैं: 3x + 2 को 5x नहीं लिखा जा सकता।',
  'misconception.juxtapositionAsDigits.name': 'अक्षर के पास की संख्या को अंक समझा गया',
  'misconception.juxtapositionAsDigits.explain': '3a का अर्थ 3 × a है। यह दो अंकों की संख्या नहीं है।',
  'misconception.negativeSquared.name': 'घात लगाते समय ऋणात्मक संख्या का कोष्ठक छूट गया',
  'misconception.negativeSquared.explain': '(−a)² = a², पर −a² का अर्थ a² का ऋणात्मक है। कोष्ठक ही तय करता है।',
  'misconception.powerOfPower.name': 'घात की घात में घातांक जोड़े गए, गुणा नहीं किए गए',
  'misconception.powerOfPower.explain': '(xᵃ)ᵇ = xᵃᵇ: घातांकों का गुणा करें। जोड़ना xᵃ · xᵇ के लिए होता है।',
  'misconception.powerProduct.name': 'घातांक का नियम उल्टा लगाया गया',
  'misconception.powerProduct.explain': 'समान आधार पर गुणा करने पर घातांक जुड़ते हैं और भाग करने पर घटते हैं।',
  'misconception.powerAsMultiplication.name': 'घात को गुणा समझा गया',
  'misconception.powerAsMultiplication.explain': '2³ का अर्थ 2 × 2 × 2 है, 2 × 3 नहीं।',
  'misconception.negativeIndexAsNegative.name': 'ऋणात्मक घातांक को ऋणात्मक संख्या समझा गया',
  'misconception.negativeIndexAsNegative.explain': 'ऋणात्मक घातांक का अर्थ व्युत्क्रम है: x⁻ⁿ = 1/xⁿ, जो ऋणात्मक नहीं है।',
  'misconception.functionOfSum.name': 'फलन को योग पर बाँट दिया गया',
  'misconception.functionOfSum.explain': '√(a + b) बराबर √a + √b नहीं होता। पहले योग निकालें।',
  'misconception.fractionAcross.name': 'भिन्नों के अंश और हर सीधे जोड़ दिए गए',
  'misconception.fractionAcross.explain': 'भिन्नों को जोड़ने से पहले हर एक जैसे करने होते हैं। हरों को कभी नहीं जोड़ा जाता।',
  'misconception.cancelOverSum.name': 'योग के केवल एक पद से भाग या निरसन किया गया',
  'misconception.cancelOverSum.explain': 'हर पूरे अंश को भाग देता है। पहले गुणनखंड करें, फिर केवल उभयनिष्ठ गुणनखंड काटें।',
  'misconception.reciprocalFlip.name': 'भिन्न उल्टी लिखी गई',
  'misconception.reciprocalFlip.explain': 'भिन्न लिखने से पहले जाँचें कि कौन-सी राशि ऊपर आती है।',
  'misconception.lostRoot.name': 'एक हल छूट गया',
  'misconception.lostRoot.explain': 'वर्गमूल लेने पर दो शाखाएँ बनती हैं: x² = k का अर्थ x = ±√k है।',
  'misconception.dividedByVariable.name': 'दोनों पक्षों को चर से भाग दिया गया',
  'misconception.dividedByVariable.explain': 'x से भाग देने पर हल x = 0 खो जाता है। इसके बजाय गुणनखंड करें और हर गुणनखंड को शून्य रखें।',
  'misconception.rootSignFromFactor.name': 'गुणनखंड से मूल गलत चिह्न के साथ पढ़ा गया',
  'misconception.rootSignFromFactor.explain': 'यदि (x − a) = 0 है तो x = a: मूल का चिह्न कोष्ठक की संख्या से उल्टा होता है।',
  'misconception.perpendicularGradient.name': 'लंब की प्रवणता ऋणात्मक व्युत्क्रम नहीं ली गई',
  'misconception.perpendicularGradient.explain': 'लंब रेखाओं की प्रवणताओं का गुणनफल −1 होता है: भिन्न उल्टी करें और चिह्न बदलें।',
  'misconception.probabilityWrongTotal.name': 'प्रायिकता गलत कुल से निकाली गई',
  'misconception.probabilityWrongTotal.explain': 'प्रायिकता = अनुकूल परिणाम ÷ सभी समसंभावी परिणाम।',
  'misconception.signFlipped.name': 'चिह्न अपने आप बदल गया',
