  'ncert.rnHowPriMarksBody': 'बनाए गए प्रश्न-बैंक में अध्याय के हर कौशल के चार स्तर हैं। संख्यात्मक प्रश्न हैंडराइटिंग के लिए तैयार हैं; गुणधर्म से जुड़े अवधारणात्मक प्रश्नों में MCQ वहाँ है जहाँ हैंडराइटिंग पहचान से गणितीय लाभ के बजाय केवल अड़चन बढ़ती। हर प्रश्न में क्रमिक संकेत, गलत धारणा के अनुसार प्रतिक्रिया और जाँच के बाद दिखने वाला चरण-दर-चरण पूरा हल है।',
