  'accountAction.withdrawIntro': 'आपने पहले इस Pri Learning खाते की पुष्टि की थी। सहमति वापस लेने पर उनका खाता तुरंत सिंक होना बंद हो जाता है: उनका कुछ भी और उनके डिवाइस से बाहर नहीं जाता, और जो उन्होंने अब तक किया है वह उसी पर रहता है। यह लिंक केवल सहमति वापस ले सकता है, दे नहीं सकता, और एक ही बार काम करता है।',
