  'deleteRequest.title': 'अपना Pri Learning खाता मिटाएँ',
  'deleteRequest.lead': 'यह पन्ना उन सभी के लिए है जो अपना Pri Learning क्लाउड खाता मिटाना चाहते हैं — उनके लिए भी जिनके पास अब ऐप नहीं है।',
  'deleteRequest.inAppHeading': 'ऐप में',
  'deleteRequest.inApp': 'सेटिंग्स → खाता → क्लाउड खाता मिटाएँ खोलें। आप अपने पासवर्ड से, अपने Apple या Google साइन-इन से, या अपने ईमेल पते या मोबाइल नंबर पर भेजे गए कोड से पुष्टि करते हैं, और खाता तुरंत मिट जाता है।',
  'deleteRequest.hereHeading': 'यहाँ, बिना साइन इन किए',
  'deleteRequest.here': 'वह ईमेल पता लिखें जिससे खाता बना था। हम उस पर 6 अंकों का कोड भेजते हैं; कोड दर्ज करें और खाता तुरंत मिट जाता है। केवल मोबाइल नंबर से बना खाता ऐप में, उस नंबर पर भेजे गए कोड से मिटाया जाता है।',
  'deleteRequest.whatHeading': 'क्या मिटता है',
  'deleteRequest.what': 'आपकी प्रोफ़ाइल, साइन-इन का विवरण और हर सत्र, आपका सिंक किया हुआ काम, आपकी कक्षाओं की सदस्यता और जमा किया गया काम, सदस्यता का जुड़ाव, आपकी टेलीमेट्री और किसी भी अभिभावक का विवरण — तुरंत, बिना किसी प्रतीक्षा-अवधि के। तीन चीज़ें रहती हैं, और उनमें ऐसा कुछ नहीं होता जिससे आपकी पहचान हो: आपके किए किसी भुगतान का रिकॉर्ड (जिसे कर और लेखा क़ानून के अनुसार हमें रखना होता है), किसी प्रश्न के बारे में आपकी भेजी शिकायत जिसमें से आपके शब्द हटा दिए जाते हैं, और एक लॉग प्रविष्टि कि एक खाता मिटाया गया।',
  'deleteRequest.device': 'आपके अपने डिवाइस पर सहेजा काम इससे प्रभावित नहीं होता; उसे उस डिवाइस की सेटिंग्स से मिटाएँ। यदि आपने Apple के ज़रिए सदस्यता ली है, तो अपनी Apple ID सेटिंग्स में सदस्यता भी रद्द करें — खाता मिटाने से वह रद्द नहीं होती।',
